Node (axios + tiny backoff):

const axios = require('axios');
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function callInference(payload, maxAttempts = 4) {
  let attempt = 0;
  while (attempt < maxAttempts) {
    try {
      const res = await axios.post(process.env.REDWOOD_ENDPOINT, payload, { timeout: 15000 });
      return res.data;
    } catch (err) {
      attempt++;
      const retryAfter = err.response && err.response.headers['retry-after'];
      if (retryAfter) await sleep(parseInt(retryAfter, 10) * 1000);
      else {
        const base = 200 * Math.pow(2, attempt - 1);
        const jitter = Math.floor(Math.random() * base);
        await sleep(base + jitter);
      }
      if (attempt >= maxAttempts) throw err;
    }
  }
}

Python (requests + backoff):

import requests, time, random

 def call_inference(payload, max_attempts=4):
    attempt = 0
    while attempt < max_attempts:
        try:
            r = requests.post(os.environ['REDWOOD_ENDPOINT'], json=payload, timeout=15)
            r.raise_for_status()
            return r.json()
        except requests.exceptions.HTTPError as he:
            attempt += 1
            if r.status_code == 429:
                retry_after = r.headers.get('Retry-After')
                if retry_after:
                    time.sleep(int(retry_after))
                    continue
            backoff_base = 0.2 * (2 ** (attempt - 1))
            time.sleep(backoff_base + random.random() * backoff_base)
            if attempt >= max_attempts:
                raise

